import React, { useEffect, useState } from "react";
import { Box, Typography, Avatar, IconButton, TextField, Button, Collapse } from "@mui/material";
import FavoriteIcon from "@mui/icons-material/Favorite";
import ReplyIcon from "@mui/icons-material/Reply";
import ExpandMoreIcon from "@mui/icons-material/ExpandMore";
import ExpandLessIcon from "@mui/icons-material/ExpandLess";
import Cookies from "js-cookie";
import { User } from "firebase/auth";
import Reply from "./Reply";
import { useTranslation } from "../../../hooks/useTranslation";

interface CommentProps {
  comment: any;
  user: User | null;
  replies?: any[];
  postID: number | null;
  onReplySubmitted?: () => void;
}

// Function to process @ mentions in the content
const processMentions = (content: string) => {
  if (!content) return content;
  
  // Pattern to match @username mentions (alphanumeric, underscore, dot)
  const mentionPattern = /@(\w+(?:\.\w+)?)/g;
  
  return content.replace(mentionPattern, (match, username) => {
    return `<span style="color: #1976d2; font-weight: 500; cursor: pointer;" onclick="alert('User: ${username}')">@${username}</span>`;
  });
};

const Comment: React.FC<CommentProps> = ({ comment, user, replies = [], postID, onReplySubmitted }) => {
  const { t } = useTranslation();
  const [likes, setLikes] = useState(comment.likes || 0);
  const [liked, setLiked] = useState(false);
  const [showReplies, setShowReplies] = useState(false);
  const [showReplyForm, setShowReplyForm] = useState(false);
  const [replyText, setReplyText] = useState("");
  const [submittingReply, setSubmittingReply] = useState(false);
  const [repliesList, setRepliesList] = useState(replies);
  const [pendingReplies, setPendingReplies] = useState<any[]>([]); // Store locally added replies that haven't been confirmed by API yet
  const userId = Cookies.get("userId");
  const wpToken = Cookies.get("wpToken");
  const WP_API_URL = process.env.REACT_APP_WP_API_URL;

  const handleLike = async () => {
    const action = liked ? "unlike" : "like";
    try {
      // Log auth details for debugging
      console.log("Auth token type:", typeof wpToken);
      console.log("Auth token length:", wpToken ? wpToken.length : 0);
      console.log("User email:", user?.email);

      const response = await fetch(
        `${process.env.REACT_APP_WP_API_URL_CUSTOM}/like-comment/${comment?.id}`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "Authorization": `Basic ${btoa(`${user?.email || ""}:${wpToken}`)}`,
          },
          body: JSON.stringify({ action }),
        }
      );
      const data = await response.json();
      setLikes(data.likes);
      setLiked(!liked);
    } catch (error) {
      console.error("Error liking comment:", error);
    }
  };

  const likedUsers = comment?.liked_users ? Object.values(comment.liked_users) : [];

  useEffect(() => {
    if (userId && likedUsers.includes(parseInt(userId))) {
      setLiked(true);
    }
  }, [comment.likes, userId, likedUsers]);

  useEffect(() => {
    // Merge fetched replies with any pending (locally added) replies
    // This ensures locally added replies don't disappear while waiting for API confirmation
    setPendingReplies((currentPending) => {
      if (!replies || replies.length === 0) {
        // If no fetched replies, keep pending ones
        if (currentPending.length > 0) {
          setRepliesList(currentPending);
        }
        return currentPending;
      }
      
      const fetchedReplyIds = new Set(replies.map((r: any) => r.id));
      
      // Filter out pending replies that now exist in fetched replies (they've been confirmed by API)
      const stillPending = currentPending.filter((pending: any) => !fetchedReplyIds.has(pending.id));
      
      // Merge confirmed replies with still-pending ones (those not yet in API response)
      const mergedReplies = [...replies, ...stillPending];
      setRepliesList(mergedReplies);
      
      return stillPending;
    });
  }, [replies]);

  const handleReplySubmit = async () => {
    if (!replyText.trim() || !user || !wpToken || !postID) return;

    setSubmittingReply(true);
    try {
      console.log("Submitting reply:", { post: postID, parent: comment.id, content: replyText });
      
      const response = await fetch(`${WP_API_URL}/comments`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Basic ${btoa(`${user?.email || ""}:${wpToken}`)}`,
        },
        body: JSON.stringify({
          content: replyText,
          post: postID,
          parent: comment.id, // Set parent to reply to this comment
          meta: {
            translation: comment.translation || comment.meta?.translation || 'kjv', // Inherit translation from parent comment
          },
        }),
      });

      if (!response.ok) {
        const errorText = await response.text();
        console.error("Failed to post reply:", response.status, errorText);
        throw new Error(`Failed to post reply: ${response.status} ${errorText}`);
      }

      const newReply = await response.json();
      console.log("Reply created:", newReply);
      
      // Add the parent author name to the reply for display
      newReply.parent_author_name = comment.author_name;
      
      // Initialize likes and liked_users if not present
      if (!newReply.likes) {
        newReply.likes = 0;
      }
      if (!newReply.liked_users) {
        newReply.liked_users = {};
      }
      
      // Add the new reply to pending replies and show replies immediately
      setPendingReplies((prev) => {
        console.log("Adding reply to pending. Previous count:", prev.length);
        const updated = [...prev, newReply];
        console.log("New pending count:", updated.length);
        return updated;
      });
      
      // Also add to the replies list immediately for instant display
      setRepliesList((prev) => {
        // Check if reply already exists to avoid duplicates
        if (prev.some((r: any) => r.id === newReply.id)) {
          return prev;
        }
        return [...prev, newReply];
      });
      
      setShowReplies(true); // Auto-expand replies when a new one is added
      setReplyText("");
      setShowReplyForm(false);
      
      // Wait a bit before refreshing to ensure WordPress has processed the reply
      // Then refresh comments to get the full reply data from the API
      setTimeout(() => {
        console.log("Refreshing comments after reply submission");
        if (onReplySubmitted) {
          onReplySubmitted();
        }
      }, 1500); // Increased delay to 1.5 seconds to give WordPress more time to process
    } catch (error) {
      console.error("Error submitting reply:", error);
      alert(`Failed to post reply: ${error instanceof Error ? error.message : 'Unknown error'}`);
    } finally {
      setSubmittingReply(false);
    }
  };

  const processedContent = comment?.content?.rendered 
    ? processMentions(comment.content.rendered) 
    : '';

  const replyCount = repliesList.length;

  return (
    <Box sx={{ mb: 2 }}>
      <Box
        sx={{
          display: "flex",
          alignItems: "flex-start",
          mb: 0,
        }}
      >
        <Avatar
          alt={comment.author_name}
          src={comment.author_avatar_urls?.[48]}
          sx={{ mr: 1, width: "24px", height: "24px", borderRadius: "0px" }}
        />
        <Box sx={{ flex: 1 }}>
          <Typography variant="body2" sx={{ fontWeight: "bold", color: "black" }}>
            {comment.author_name}
          </Typography>
          <Typography
            variant="body2"
            sx={{
              px: 2,
              mt: -1.85,
              lineHeight: 1.1,
              fontSize: "14px",
              color: "black",
              wordBreak: "break-word",
              whiteSpace: "pre-wrap",
              overflowWrap: "break-word",
              textAlign: "justify",
              fontFamily: "'Alegreya Sans', sans-serif",
              '& a': {
                color: '#a1a1a1',
                textDecoration: 'underline',
                transition: 'color 0.2s ease',
                '&:hover': {
                  color: 'black',
                }
              }
            }}
            dangerouslySetInnerHTML={{ __html: processedContent }}
          />
          <Box sx={{ display: "flex", alignItems: "center", mt: -4 }}>
            <IconButton
              size="small"
              onClick={handleLike}
              color={liked || likedUsers.includes(parseInt(userId ? userId : '0')) ? "warning" : "secondary"}
            >
              <FavoriteIcon
                sx={{ 
                  color: liked || likedUsers.includes(parseInt(userId ? userId : '0')) ? "warning" : "secondary", 
                  width: "18px" 
                }}
                fontSize="small"
              />
            </IconButton>
            <Typography
              variant="body2"
              sx={{
                ml: 0,
                mt: "-1.75px",
                color: "#777",
                fontSize: "14px",
                fontWeight: 800,
                lineHeight: 'normal',
                fontFamily: "'Alegreya Sans', sans-serif",
              }}
            >
              {likes}
            </Typography>
            
            {/* Show/hide replies button - visible to everyone */}
            {replyCount > 0 && (
              <>
                <IconButton
                  size="small"
                  onClick={() => setShowReplies(!showReplies)}
                  sx={{ ml: 1 }}
                >
                  {showReplies ? (
                    <ExpandLessIcon sx={{ width: "16px", height: "16px", color: "#777" }} />
                  ) : (
                    <ExpandMoreIcon sx={{ width: "16px", height: "16px", color: "#777" }} />
                  )}
                </IconButton>
                <Typography
                  variant="body2"
                  sx={{
                    ml: 0.5,
                    mt: "-1.75px",
                    color: "#777",
                    fontSize: "12px",
                    cursor: "pointer",
                    '&:hover': {
                      textDecoration: 'underline'
                    }
                  }}
                  onClick={() => setShowReplies(!showReplies)}
                >
                  {replyCount} {replyCount === 1 ? String(t('comments.replySingular')) : String(t('comments.replies'))}
                </Typography>
              </>
            )}
            
            {/* Reply button - only visible when logged in */}
            {user && (
              <IconButton
                size="small"
                onClick={() => {
                  setShowReplyForm(!showReplyForm);
                  if (!showReplyForm) {
                    setReplyText(`@${comment.author_name} `);
                  }
                }}
                sx={{ ml: replyCount > 0 ? 1 : 1 }}
              >
                <ReplyIcon sx={{ width: "16px", height: "16px", color: "#777" }} fontSize="small" />
              </IconButton>
            )}
          </Box>
          
          {/* Reply form */}
          {showReplyForm && user && (
            <Box sx={{ mt: 2, ml: 2 }}>
              <TextField
                placeholder={String(t('comments.replyTo', { name: comment.author_name }))}
                value={replyText}
                onChange={(e) => setReplyText(e.target.value)}
                multiline
                rows={2}
                fullWidth
                size="small"
                sx={{
                  mb: 1,
                  WebkitBoxShadow: "none !important",
                  "& .MuiInputBase-root": {
                    backgroundColor: (theme) =>
                      theme.palette.mode === "light" ? "white" : "#424242",
                  },
                  "& .MuiOutlinedInput-notchedOutline": {
                    borderColor: (theme) =>
                      theme.palette.mode === "light" ? "#ccc" : "rgba(255, 255, 255, 0.23)",
                  },
                  "&:hover .MuiOutlinedInput-notchedOutline": {
                    borderColor: (theme) =>
                      theme.palette.mode === "light" ? "#999" : "rgba(255, 255, 255, 0.4)",
                  },
                  "& .Mui-focused": {
                    color: (theme) =>
                      theme.palette.mode === "light"
                        ? "black !important"
                        : "white !important",
                    "& .MuiOutlinedInput-notchedOutline": {
                      borderColor: (theme) =>
                        theme.palette.mode === "light"
                          ? "#ccc !important"
                          : "#FFF !important",
                      color: (theme) =>
                        theme.palette.mode === "light"
                          ? "black"
                          : "white !important",
                    },
                    "& input:-webkit-autofill": {
                      WebkitBoxShadow: "0 0 0 100px #212121AA inset",
                      WebkitTextFillColor: (theme) =>
                        theme.palette.mode === "light" ? "black" : "white",
                      transition: "background-color 5000s ease-in-out 0s",
                    },
                    "& .MuiInputBase-root": {
                      backgroundColor: (theme) =>
                        theme.palette.mode === "light" ? "white" : "#424242",
                    },
                  },
                  "& .MuiInputBase-input": {
                    color: (theme) =>
                      theme.palette.mode === "light" ? "black" : "white",
                    fontSize: '13px',
                    "&::placeholder": {
                      color: (theme) =>
                        theme.palette.mode === "light" ? "rgba(0, 0, 0, 0.6)" : "rgba(255, 255, 255, 0.6)",
                      opacity: 1,
                    },
                  },
                  "& .MuiInputBase-input:-webkit-autofill": {
                    WebkitBoxShadow: "0 0 0 100px #212121AA inset",
                    WebkitTextFillColor: (theme) =>
                      theme.palette.mode === "light" ? "black" : "white",
                    transition: "background-color 5000s ease-in-out 0s",
                  },
                }}
              />
              <Box sx={{ display: "flex", gap: 1 }}>
                <Button
                  size="small"
                  variant="contained"
                  color="success"
                  onClick={handleReplySubmit}
                  disabled={submittingReply || !replyText.trim()}
                  sx={{ 
                    fontSize: "12px", 
                    py: 0.5,
                    backgroundColor: "#a1a1a1",
                    "&:hover": {
                      backgroundColor: "success",
                    },
                  }}
                >
                  {submittingReply ? String(t('comments.posting')) : String(t('comments.reply'))}
                </Button>
                <Button
                  size="small"
                  variant="outlined"
                  onClick={() => {
                    setShowReplyForm(false);
                    setReplyText("");
                  }}
                  sx={{ 
                    fontSize: "12px", 
                    py: 0.5,
                    borderColor: (theme) =>
                      theme.palette.mode === "light" ? "#ccc" : "rgba(255, 255, 255, 0.23)",
                    color: (theme) =>
                      theme.palette.mode === "light" ? "black" : "white",
                    "&:hover": {
                      borderColor: (theme) =>
                        theme.palette.mode === "light" ? "#999" : "rgba(255, 255, 255, 0.4)",
                      backgroundColor: (theme) =>
                        theme.palette.mode === "light" ? "rgba(0, 0, 0, 0.04)" : "rgba(255, 255, 255, 0.08)",
                    },
                  }}
                >
                  {String(t('comments.cancel'))}
                </Button>
              </Box>
            </Box>
          )}
        </Box>
      </Box>
      
      {/* Replies */}
      {replyCount > 0 && (
        <Collapse in={showReplies}>
          <Box sx={{ mt: 1 }}>
            {repliesList.map((reply) => (
              <Reply
                key={reply.id}
                reply={reply}
                user={user}
                onReply={(reply) => {
                  // Could add nested replies in the future
                  console.log('Reply to reply:', reply);
                }}
              />
            ))}
          </Box>
        </Collapse>
      )}
    </Box>
  );
};

export default Comment;
